// nodaysoffai.com — static site + lead intake + image proxy (GitHub-backed, edge-cached)
const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>No Days Off AI — Your Business. Always On.</title>\n<meta name=\"description\" content=\"Custom AI systems for small businesses. We answer your calls, follow up your quotes, earn your reviews, and watch your competition — 24/7.\">\n<style>\n  :root{\n    --bg:#000;\n    --light:#f5f5f7;\n    --text:#f5f5f7;\n    --text-dark:#1d1d1f;\n    --gray:#86868b;\n    --blue:#2997ff;\n    --radius:28px;\n  }\n  *{margin:0;padding:0;box-sizing:border-box;-webkit-font-smoothing:antialiased}\n  html{scroll-behavior:smooth}\n  body{\n    font-family:-apple-system,BlinkMacSystemFont,\"SF Pro Display\",\"SF Pro Text\",\"Helvetica Neue\",Helvetica,Arial,sans-serif;\n    background:var(--bg);color:var(--text);\n    letter-spacing:-0.01em;\n    overflow-x:hidden;\n  }\n  img{max-width:100%;display:block}\n  a{color:var(--blue);text-decoration:none}\n  a:hover{text-decoration:underline}\n\n  /* ---------- NAV ---------- */\n  nav{\n    position:fixed;top:0;left:0;right:0;z-index:100;\n    backdrop-filter:saturate(180%) blur(20px);\n    -webkit-backdrop-filter:saturate(180%) blur(20px);\n    background:rgba(22,22,23,.72);\n    border-bottom:1px solid rgba(255,255,255,.08);\n  }\n  .nav-inner{\n    max-width:1024px;margin:0 auto;height:52px;\n    display:flex;align-items:center;justify-content:space-between;\n    padding:0 22px;\n  }\n  .nav-logo{font-size:15px;font-weight:600;color:#f5f5f7;letter-spacing:.01em}\n  .nav-logo:hover{text-decoration:none}\n  .nav-links{display:flex;gap:34px}\n  .nav-links a{font-size:12px;color:#d6d6da;font-weight:400}\n  .nav-links a:hover{color:#fff;text-decoration:none}\n  .nav-cta{\n    font-size:12px;background:var(--blue);color:#fff!important;\n    padding:6px 14px;border-radius:980px;font-weight:500;\n  }\n  .nav-cta:hover{background:#2ea1ff;text-decoration:none}\n  @media(max-width:734px){.nav-links{display:none}}\n\n  /* ---------- SECTIONS ---------- */\n  section{padding:110px 22px;position:relative}\n  .wrap{max-width:1024px;margin:0 auto}\n  .narrow{max-width:760px;margin:0 auto;text-align:center}\n\n  .eyebrow{\n    font-size:21px;font-weight:600;color:var(--gray);\n    margin-bottom:14px;\n  }\n  h1{\n    font-size:clamp(48px,8vw,96px);\n    font-weight:700;line-height:1.02;letter-spacing:-0.028em;\n  }\n  h2{\n    font-size:clamp(36px,5.4vw,64px);\n    font-weight:700;line-height:1.06;letter-spacing:-0.024em;\n  }\n  h3{font-size:24px;font-weight:600;letter-spacing:-0.016em}\n  .sub{\n    font-size:clamp(17px,2vw,21px);line-height:1.5;\n    color:var(--gray);margin-top:22px;font-weight:400;\n  }\n  .sub-dark{color:#6e6e73}\n  .link-arrow{font-size:19px;font-weight:400;display:inline-block;margin-top:26px}\n  .link-arrow::after{content:\" ›\";font-weight:600}\n\n  .gradient-text{\n    background:linear-gradient(92deg,#4db2ff 0%,#a06bff 55%,#5fe0d0 100%);\n    -webkit-background-clip:text;background-clip:text;\n    -webkit-text-fill-color:transparent;color:transparent;\n  }\n\n  /* ---------- HERO ---------- */\n  .hero{padding:180px 22px 0;text-align:center;background:#000}\n  .hero .sub{max-width:640px;margin-left:auto;margin-right:auto}\n  .hero-img{\n    max-width:900px;margin:30px auto 0;\n    mask-image:linear-gradient(to bottom,black 78%,transparent 100%);\n    -webkit-mask-image:linear-gradient(to bottom,black 78%,transparent 100%);\n  }\n  .hero-ctas{margin-top:34px;display:flex;gap:30px;justify-content:center;flex-wrap:wrap}\n  .btn-pill{\n    background:var(--blue);color:#fff;font-size:17px;font-weight:500;\n    padding:12px 26px;border-radius:980px;display:inline-block;\n  }\n  .btn-pill:hover{background:#2ea1ff;text-decoration:none}\n\n  /* ---------- LIGHT SECTIONS ---------- */\n  .light{background:var(--light);color:var(--text-dark)}\n  .light .eyebrow{color:#6e6e73}\n\n  .split{\n    display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center;\n  }\n  @media(max-width:834px){.split{grid-template-columns:1fr;gap:44px}}\n  .split img{border-radius:var(--radius);width:100%}\n\n  /* ---------- BENTO ---------- */\n  .bento{\n    display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin-top:60px;\n  }\n  @media(max-width:734px){.bento{grid-template-columns:1fr}}\n  .bento-card{\n    background:#fff;border-radius:var(--radius);padding:44px 40px;\n    text-align:left;transition:transform .35s cubic-bezier(.2,.6,.2,1),box-shadow .35s;\n  }\n  .bento-card:hover{transform:translateY(-4px);box-shadow:0 20px 50px rgba(0,0,0,.08)}\n  .bento-icon{\n    width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;\n    margin-bottom:20px;font-size:22px;\n    background:linear-gradient(135deg,#0a84ff22,#bf5af222);\n  }\n  .bento-card p{font-size:15px;line-height:1.55;color:#6e6e73;margin-top:10px}\n  .bento-card h3{color:var(--text-dark)}\n\n  /* ---------- DARK PRODUCT SECTIONS ---------- */\n  .product{text-align:center}\n  .product img{margin:56px auto 0;max-width:420px}\n  .product img.wide{max-width:820px;border-radius:var(--radius)}\n  .glow{\n    position:absolute;inset:0;pointer-events:none;\n    background:radial-gradient(600px 400px at 50% 100%,rgba(76,140,255,.14),transparent 70%);\n  }\n\n  /* ---------- STATS ---------- */\n  .stats{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;text-align:center}\n  @media(max-width:734px){.stats{grid-template-columns:1fr;gap:44px}}\n  .stat-num{font-size:clamp(44px,6vw,72px);font-weight:700;letter-spacing:-0.03em}\n  .stat-label{font-size:15px;color:var(--gray);margin-top:8px}\n\n  /* ---------- STEPS ---------- */\n  .steps{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:64px;text-align:left}\n  @media(max-width:734px){.steps{grid-template-columns:1fr}}\n  .step{\n    background:#fff;border-radius:var(--radius);padding:40px 34px;\n  }\n  .step-num{\n    font-size:15px;font-weight:600;color:var(--blue);margin-bottom:16px;\n  }\n  .step h3{color:var(--text-dark);font-size:20px}\n  .step p{font-size:15px;line-height:1.55;color:#6e6e73;margin-top:10px}\n\n  /* ---------- CTA ---------- */\n  .cta{padding:150px 22px;text-align:center;background:#000;position:relative}\n\n  /* ---------- CONSULT FORM ---------- */\n  .consult-form{\n    max-width:640px;margin:56px auto 0;text-align:left;\n    background:rgba(255,255,255,.06);\n    border:1px solid rgba(255,255,255,.12);\n    border-radius:var(--radius);padding:40px 36px;\n    backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);\n  }\n  @media(max-width:734px){.consult-form{padding:32px 22px}}\n  .form-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n  @media(max-width:560px){.form-row{grid-template-columns:1fr}}\n  .field{margin-bottom:16px}\n  .field label{\n    display:block;font-size:13px;font-weight:600;color:#a1a1a6;\n    margin-bottom:8px;letter-spacing:.01em;\n  }\n  .field .optional{font-weight:400;color:#6e6e73}\n  .field input,.field textarea{\n    width:100%;font:inherit;font-size:16px;color:#f5f5f7;\n    background:rgba(255,255,255,.08);\n    border:1px solid rgba(255,255,255,.14);\n    border-radius:14px;padding:14px 16px;outline:none;\n    transition:border-color .2s,box-shadow .2s;\n  }\n  .field textarea{resize:vertical;min-height:110px}\n  .field input::placeholder,.field textarea::placeholder{color:#6e6e73}\n  .field input:focus,.field textarea:focus{\n    border-color:var(--blue);\n    box-shadow:0 0 0 4px rgba(41,151,255,.25);\n  }\n  .hp{position:absolute;left:-9999px;width:1px;height:1px;opacity:0}\n  .form-submit{\n    width:100%;border:none;cursor:pointer;font-size:17px;\n    padding:15px 26px;margin-top:8px;transition:background .2s,opacity .2s;\n  }\n  .form-submit:disabled{opacity:.6;cursor:default}\n  .form-note{font-size:12px;color:#6e6e73;text-align:center;margin-top:16px;line-height:1.5}\n  .form-error{font-size:14px;color:#ff6961;text-align:center;margin-top:14px;min-height:0}\n  .form-success{\n    max-width:640px;margin:56px auto 0;text-align:center;\n    background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);\n    border-radius:var(--radius);padding:64px 36px;\n  }\n  .success-check{\n    width:64px;height:64px;border-radius:50%;margin:0 auto 24px;\n    background:linear-gradient(135deg,#30d158,#28c76f);\n    display:flex;align-items:center;justify-content:center;\n    font-size:30px;color:#fff;font-weight:700;\n  }\n  .form-success h3{font-size:28px;margin-bottom:10px}\n  .form-success p{color:var(--gray);font-size:17px}\n\n  /* ---------- FOOTER ---------- */\n  footer{\n    background:#161617;padding:44px 22px 60px;\n    font-size:12px;color:var(--gray);\n  }\n  .foot-inner{max-width:1024px;margin:0 auto}\n  .foot-links{display:flex;gap:26px;flex-wrap:wrap;margin-bottom:20px}\n  .foot-links a{color:#d6d6da;font-size:12px}\n  .foot-line{border-top:1px solid rgba(255,255,255,.12);padding-top:18px;line-height:1.7}\n\n  /* ---------- REVEAL ---------- */\n  .reveal{opacity:0;transform:translateY(28px);transition:opacity .8s cubic-bezier(.2,.6,.2,1),transform .8s cubic-bezier(.2,.6,.2,1)}\n  .reveal.in{opacity:1;transform:none}\n  @media(prefers-reduced-motion:reduce){\n    html{scroll-behavior:auto}\n    .reveal{opacity:1;transform:none;transition:none}\n  }\n</style>\n</head>\n<body>\n\n<nav>\n  <div class=\"nav-inner\">\n    <a class=\"nav-logo\" href=\"#top\">No Days Off AI</a>\n    <div class=\"nav-links\">\n      <a href=\"#solutions\">Solutions</a>\n      <a href=\"#answering\">Call Answering</a>\n      <a href=\"#intel\">Competitor Intel</a>\n      <a href=\"#how\">How It Works</a>\n    </div>\n    <a class=\"nav-cta\" href=\"#contact\">Book a Free Call</a>\n  </div>\n</nav>\n\n<!-- HERO -->\n<section class=\"hero\" id=\"top\">\n  <div class=\"eyebrow reveal\">No Days Off AI</div>\n  <h1 class=\"reveal\">Your business.<br><span class=\"gradient-text\">Always on.</span></h1>\n  <p class=\"sub reveal\">We build custom AI systems for small businesses — answering every call, following up every quote, earning every review, and watching your competition around the clock. Built around how <em>you</em> actually work.</p>\n  <div class=\"hero-ctas reveal\">\n    <a class=\"btn-pill\" href=\"#contact\">Book a free call</a>\n    <a class=\"link-arrow\" href=\"#solutions\" style=\"margin-top:12px\">See what we build</a>\n  </div>\n  <img class=\"hero-img reveal\" src=\"images/hero.webp\" alt=\"No Days Off AI\">\n</section>\n\n<!-- LIFESTYLE / PROBLEM -->\n<section class=\"light\">\n  <div class=\"wrap split\">\n    <div class=\"reveal\">\n      <div class=\"eyebrow\">Sound familiar?</div>\n      <h2>You do the work.<br>Who does everything else?</h2>\n      <p class=\"sub sub-dark\">You're on a roof, under a sink, or elbow-deep in a job — and the phone rings. That missed call is a $4,000 job going to the guy who picked up. The quote you sent Tuesday? Nobody followed up. The happy customer from last week? Never asked for a review.</p>\n      <p class=\"sub sub-dark\">That's not a you problem. It's a hours-in-the-day problem. We fix it.</p>\n      <a class=\"link-arrow\" href=\"#solutions\">Here's how</a>\n    </div>\n    <div class=\"reveal\">\n      <img src=\"images/lifestyle.webp\" alt=\"A small business owner on the job\">\n    </div>\n  </div>\n</section>\n\n<!-- SOLUTIONS BENTO -->\n<section class=\"light\" id=\"solutions\" style=\"padding-top:20px\">\n  <div class=\"wrap\">\n    <div class=\"narrow reveal\">\n      <div class=\"eyebrow\">What we build</div>\n      <h2>Not a chatbot.<br>A crew that never sleeps.</h2>\n      <p class=\"sub sub-dark\">Every system is custom-built around your workflow, your customers, and the way you talk. Not a template. Not off the shelf.</p>\n    </div>\n    <div class=\"bento\">\n      <div class=\"bento-card reveal\">\n        <div class=\"bento-icon\">📞</div>\n        <h3>24/7 call answering</h3>\n        <p>Every call answered on the first ring — nights, weekends, holidays. It sounds like your business because we train it on your business.</p>\n      </div>\n      <div class=\"bento-card reveal\">\n        <div class=\"bento-icon\">💬</div>\n        <h3>Quote follow-up</h3>\n        <p>Quotes go cold in 48 hours. Our system follows up automatically until you get a yes or a no — most jobs are won on the second touch.</p>\n      </div>\n      <div class=\"bento-card reveal\">\n        <div class=\"bento-icon\">⭐</div>\n        <h3>Review engine</h3>\n        <p>After every finished job, customers get a friendly nudge at the right moment. More 5-star reviews, higher Google ranking, more calls.</p>\n      </div>\n      <div class=\"bento-card reveal\">\n        <div class=\"bento-icon\">📅</div>\n        <h3>Booking & scheduling</h3>\n        <p>Customers book straight into your calendar — no phone tag, no double-bookings, no leads dying in your voicemail.</p>\n      </div>\n      <div class=\"bento-card reveal\">\n        <div class=\"bento-icon\">🛰️</div>\n        <h3>Competitor watch</h3>\n        <p>We monitor your competitors' prices, reviews, ads, and moves — and send you a 5-minute brief. You always know first.</p>\n      </div>\n      <div class=\"bento-card reveal\">\n        <div class=\"bento-icon\">⚙️</div>\n        <h3>Custom workflows</h3>\n        <p>Invoicing, reminders, intake forms, supply ordering — if you do it more than twice a week, we can probably automate it.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- PHONE PRODUCT -->\n<section class=\"product\" id=\"answering\">\n  <div class=\"glow\"></div>\n  <div class=\"wrap\">\n    <div class=\"eyebrow reveal\">Call answering</div>\n    <h2 class=\"reveal\">Every call answered.<br>Even at 2 a.m.</h2>\n    <p class=\"sub reveal\" style=\"max-width:620px;margin-left:auto;margin-right:auto\">Your AI answers in your company's voice, books the job, answers common questions, and texts you a summary. Emergencies get flagged to you instantly.</p>\n    <img class=\"reveal\" src=\"images/phone.webp\" alt=\"AI assistant answering customer messages\">\n  </div>\n</section>\n\n<!-- INTEL PRODUCT -->\n<section class=\"product\" id=\"intel\" style=\"padding-top:40px\">\n  <div class=\"glow\"></div>\n  <div class=\"wrap\">\n    <div class=\"eyebrow reveal\">Competitor intelligence</div>\n    <h2 class=\"reveal\">Know their next move.<br><span class=\"gradient-text\">Before they make it.</span></h2>\n    <p class=\"sub reveal\" style=\"max-width:640px;margin-left:auto;margin-right:auto\">While you're working, we're watching — competitor pricing changes, new ads, bad reviews you can capitalize on, jobs being posted in your area. One short brief. Only what matters.</p>\n    <img class=\"wide reveal\" src=\"images/intel.webp\" alt=\"Competitor intelligence dashboard\">\n  </div>\n</section>\n\n<!-- STATS -->\n<section class=\"light\">\n  <div class=\"wrap\">\n    <div class=\"narrow reveal\" style=\"margin-bottom:70px\">\n      <div class=\"eyebrow\">Why it matters</div>\n      <h2>The math is brutal.</h2>\n    </div>\n    <div class=\"stats\">\n      <div class=\"reveal\">\n        <div class=\"stat-num\" style=\"color:#1d1d1f\">85%</div>\n        <div class=\"stat-label\" style=\"color:#6e6e73\">of callers who hit voicemail<br>never call back</div>\n      </div>\n      <div class=\"reveal\">\n        <div class=\"stat-num\" style=\"color:#1d1d1f\">48 hrs</div>\n        <div class=\"stat-label\" style=\"color:#6e6e73\">before an unfollowed quote<br>goes to a competitor</div>\n      </div>\n      <div class=\"reveal\">\n        <div class=\"stat-num\" style=\"color:#1d1d1f\">24/7</div>\n        <div class=\"stat-label\" style=\"color:#6e6e73\">your AI crew is working —<br>nights, weekends, holidays</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- HOW IT WORKS -->\n<section class=\"light\" id=\"how\" style=\"padding-top:20px\">\n  <div class=\"wrap\">\n    <div class=\"narrow reveal\">\n      <div class=\"eyebrow\">How it works</div>\n      <h2>Three steps. Zero headaches.</h2>\n    </div>\n    <div class=\"steps\">\n      <div class=\"step reveal\">\n        <div class=\"step-num\">01</div>\n        <h3>We learn your business</h3>\n        <p>One conversation. We map how you actually work — your customers, your jobs, your words. No tech talk required.</p>\n      </div>\n      <div class=\"step reveal\">\n        <div class=\"step-num\">02</div>\n        <h3>We build your system</h3>\n        <p>Custom-built and tested around your workflow. You review everything before a single customer touches it.</p>\n      </div>\n      <div class=\"step reveal\">\n        <div class=\"step-num\">03</div>\n        <h3>It works. You approve.</h3>\n        <p>Your crew runs 24/7. Big decisions still come to you first — you're always in control, just never buried.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- CTA / CONSULTATION -->\n<section class=\"cta\" id=\"contact\">\n  <div class=\"glow\"></div>\n  <div class=\"narrow\">\n    <div class=\"eyebrow reveal\">Get started</div>\n    <h2 class=\"reveal\">Book your free<br><span class=\"gradient-text\">consultation.</span></h2>\n    <p class=\"sub reveal\">15 minutes. We'll show you exactly what we'd automate first — and what it would be worth to you. No pressure, no jargon, no obligation.</p>\n  </div>\n\n  <form class=\"consult-form reveal\" id=\"consultForm\" novalidate>\n    <div class=\"form-row\">\n      <div class=\"field\">\n        <label for=\"f-name\">Your name</label>\n        <input id=\"f-name\" name=\"name\" type=\"text\" autocomplete=\"name\" required placeholder=\"Tony Martinez\">\n      </div>\n      <div class=\"field\">\n        <label for=\"f-phone\">Phone number</label>\n        <input id=\"f-phone\" name=\"phone\" type=\"tel\" autocomplete=\"tel\" required placeholder=\"(512) 555-0134\">\n      </div>\n    </div>\n    <div class=\"form-row\">\n      <div class=\"field\">\n        <label for=\"f-email\">Email</label>\n        <input id=\"f-email\" name=\"email\" type=\"email\" autocomplete=\"email\" required placeholder=\"you@yourbusiness.com\">\n      </div>\n      <div class=\"field\">\n        <label for=\"f-business\">Business name</label>\n        <input id=\"f-business\" name=\"business\" type=\"text\" autocomplete=\"organization\" required placeholder=\"Martinez Roofing Co.\">\n      </div>\n    </div>\n    <div class=\"field\">\n      <label for=\"f-comment\">Anything we should know? <span class=\"optional\">(optional)</span></label>\n      <textarea id=\"f-comment\" name=\"comment\" rows=\"4\" placeholder=\"Missed calls, slow quotes, whatever's eating your time…\"></textarea>\n    </div>\n    <input type=\"text\" name=\"company\" class=\"hp\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\">\n    <button class=\"btn-pill form-submit\" type=\"submit\">Book my free consultation</button>\n    <p class=\"form-note\">We reply within one business day. Your info stays with us — never sold, never shared.</p>\n    <p class=\"form-error\" id=\"formError\" role=\"alert\"></p>\n  </form>\n\n  <div class=\"form-success\" id=\"formSuccess\" hidden>\n    <div class=\"success-check\">✓</div>\n    <h3>You're on the books.</h3>\n    <p>We'll reach out within one business day to schedule your free consultation.</p>\n  </div>\n</section>\n\n<footer>\n  <div class=\"foot-inner\">\n    <div class=\"foot-links\">\n      <a href=\"#solutions\">Solutions</a>\n      <a href=\"#answering\">Call Answering</a>\n      <a href=\"#intel\">Competitor Intel</a>\n      <a href=\"#how\">How It Works</a>\n      <a href=\"#contact\">Contact</a>\n    </div>\n    <div class=\"foot-line\">\n      No Days Off AI — custom AI systems for small businesses. Built around your workflow, your voice, and your customers.<br>\n      © 2026 No Days Off AI. All rights reserved.\n    </div>\n  </div>\n</footer>\n\n<script>\n  const io = new IntersectionObserver((entries)=>{\n    entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target);} });\n  },{threshold:0.12});\n  document.querySelectorAll('.reveal').forEach(el=>io.observe(el));\n\n  // ---- Consultation form ----\n  const consultForm = document.getElementById('consultForm');\n  consultForm.addEventListener('submit', async (e)=>{\n    e.preventDefault();\n    const err = document.getElementById('formError');\n    err.textContent = '';\n    if(!consultForm.checkValidity()){ consultForm.reportValidity(); return; }\n    const btn = consultForm.querySelector('.form-submit');\n    btn.disabled = true; btn.textContent = 'Booking…';\n    const data = Object.fromEntries(new FormData(consultForm).entries());\n    try{\n      const res = await fetch('/api/consult',{\n        method:'POST',\n        headers:{'Content-Type':'application/json'},\n        body:JSON.stringify(data)\n      });\n      if(!res.ok) throw new Error('submit failed');\n      consultForm.hidden = true;\n      const s = document.getElementById('formSuccess');\n      s.hidden = false;\n      s.scrollIntoView({behavior:'smooth',block:'center'});\n    }catch(_){\n      err.textContent = 'Something went wrong sending that. Please try again.';\n      btn.disabled = false; btn.textContent = 'Book my free consultation';\n    }\n  });\n</script>\n\n</body>\n</html>\n";

const IMAGE_BASE = 'https://raw.githubusercontent.com/martinezvincenttony-droid/multi-department-agentic-system-enterprise/master/site-assets/nodaysoffai/';
const IMAGES = new Set(['/images/hero.webp', '/images/intel.webp', '/images/lifestyle.webp', '/images/phone.webp']);

const json = (body, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });

const clean = (v, max = 500) => (typeof v === 'string' ? v.trim().slice(0, max) : '');

async function handleImage(pathname) {
  const cache = caches.default;
  const cacheKey = new Request('https://nodaysoffai.com' + pathname);
  const cached = await cache.match(cacheKey);
  if (cached) return cached;

  const name = pathname.split('/').pop();
  const upstream = await fetch(IMAGE_BASE + name);
  if (!upstream.ok) return new Response('Not found', { status: 404 });

  const res = new Response(upstream.body, {
    headers: {
      'Content-Type': 'image/webp',
      'Cache-Control': 'public, max-age=31536000, immutable',
    },
  });
  await cache.put(cacheKey, res.clone());
  return res;
}

async function handleConsult(request, env, ctx) {
  let data;
  try {
    data = await request.json();
  } catch {
    return json({ ok: false, error: 'Invalid request.' }, 400);
  }

  // Honeypot: silently accept so bots think they succeeded.
  if (data.company) return json({ ok: true });

  const name = clean(data.name, 120);
  const phone = clean(data.phone, 40);
  const email = clean(data.email, 200);
  const business = clean(data.business, 200);
  const comment = clean(data.comment, 2000);

  if (!name || !phone || !business) {
    return json({ ok: false, error: 'Name, phone, and business name are required.' }, 400);
  }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return json({ ok: false, error: 'Please enter a valid email address.' }, 400);
  }

  await env.DB.prepare(
    'INSERT INTO consultations (name, phone, email, business, comment) VALUES (?, ?, ?, ?, ?)'
  ).bind(name, phone, email, business, comment || null).run();

  ctx.waitUntil(
    fetch(env.TASKLET_WEBHOOK_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Lead-Secret': env.LEAD_SECRET },
      body: JSON.stringify({
        source: 'nodaysoffai.com',
        name, phone, email, business,
        comment: comment || null,
        submittedAt: new Date().toISOString(),
      }),
    }).catch((err) => console.error('Tasklet webhook failed:', err))
  );

  return json({ ok: true });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.pathname === '/api/consult') {
      if (request.method === 'POST') return handleConsult(request, env, ctx);
      return json({ ok: false, error: 'Method not allowed.' }, 405);
    }

    if (IMAGES.has(url.pathname)) return handleImage(url.pathname);

    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return json({ ok: false, error: 'Method not allowed.' }, 405);
    }

    return new Response(HTML, {
      headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=300' },
    });
  },
};
